<div class="toolbar"><span class="grow"></span><?php if (is_super()): ?><a class="btn btn-ghost btn-sm" href="/admin/webinars/streams"><?= icon('live', 15) ?> Streaming &amp; social</a><?php endif; ?><a class="btn btn-primary btn-sm" href="/admin/webinars/new"><?= icon('calendar', 15) ?> Schedule a webinar</a></div>
