<?php foreach ($items as $w): ?><tr><td><a href="/admin/webinars/<?= (int) $w['id'] ?>"><strong><?= e($w['title']) ?></strong></a><div class="muted xs"><?= e(ucfirst($w['kind'])) ?> · <?= e($w['host_name']) ?> · <?= (float) $w['price'] > 0 ? e(money($w['price'], $w['currency'])) : 'Free' ?></div></td><td class="small"><?= e(fmt_dt($w['start_at'])) ?></td><td><?= $w['status'] === 'live' ? badge('Live', 'live') : badge(ucfirst($w['status']), ['scheduled' => 'blue', 'ended' => '', 'draft' => 'amber', 'cancelled' => 'red'][$w['status']] ?? '') ?></td><td class="small"><?= $w['access'] === 'public' ? 'Public link' : 'Registration' ?></td><td class="num"><?= (int) $w['regs'] ?></td><td class="num"><?= (int) $w['att'] ?></td>
<td class="tbl-actions"><?php if (in_array($w['status'], ['scheduled', 'live'], true)): ?><a class="rowbtn" href="/webinars/<?= e($w['slug']) ?>/room"><?= $w['status'] === 'live' ? 'Rejoin room' : 'Open room' ?></a><?php endif; ?><a class="rowbtn" href="/admin/webinars/<?= (int) $w['id'] ?>/edit">Edit</a></td></tr><?php endforeach; ?>
<?php if (!$items): ?><tr><td colspan="7" class="center muted" style="padding:34px">No sessions yet. Start an instant session or schedule a webinar.</td></tr><?php endif; ?></tbody></table></div>
